@js:
let token = String(source.getVariable())
let type = String(source.get('type')) || '小说'
let gender = String(source.get('gender')) || '1'
let sort = []
let path = ''

let push = (title, url, layout) => sort.push({
  title,
  url,
  style: {
    layout_flexGrow: 1,
    layout_flexBasisPercent: url ? layout || 0.25 : 1
  }
})

let add = (title, query, layout) => push(
  title,
  query ? `@js:getApiUrl('${path}', {${query},page,size:10,gender:${gender}})` : '',
  query ? layout || 0.25 : 1
)

if (token == '') {
  java.longToast('\n❌未获取共享Token，请于登录界面获取共享Token后使用此书源')
  push('请先获取共享Token')
} else {
  java.longToast('\n正在进行发现页热更新，请稍等...')

  if (type == '小说' || type == '听小说') {
    try {
      let book_shelf_url = 'https://fanqienovel.com/reading/bookapi/bookshelf/info/v:version/?aid=1967&iid=0&version_code=57700&update_version_code=57700'
      let book_shelf_info = JSON.parse(java.ajax(book_shelf_url + ', ' + JSON.stringify({
        headers: {
          'Cookie': "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : (source.getLoginInfoMap() || {})['手动登录Token']),
        }
      })))

      let username = ''
      if (book_shelf_info.code == 0) {
        let uinfo = java.ajax("https://fanqienovel.com/api/user/info/v2," + JSON.stringify({ headers: { Cookie: "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : (source.getLoginInfoMap() || {})['手动登录Token']) } }))
        uinfo = JSON.parse(uinfo)
        username = uinfo.data.name || '未知用户'
      }

      let get = (path) => `@js:
let ck = "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : (source.getLoginInfoMap() || {})['手动登录Token'])

let v = xGorgon(
    "${path}",
    "offset=" + (page - 1) * 20,
    null,
    ck,
)

xGorgon(
  "multi-detail",
  "book_id=" + getBookId(java.ajax(v)),
  null,
  ck,
)`

      if (username != '') {
        push(username + '的个人中心', '', 1)
        push('首页推荐', "https://fanqienovel.com/tab/0", 0.4)
        push('猜你喜欢', "https://fanqienovel.com/tab/2", 0.4)
        push("阅读历史", get("read_history/list"), 1)
        push("我的书架", "https://fanqienovel.com/fqbookshelf", 1)
        let groups = Array.from(new Set(book_shelf_info.data.book_shelf_info.map(i => i.group_name)))
        groups.forEach(g => g && push(g, "https://fanqienovel.com/fqbookshelf/groupName/" + g, 0.4))
      }
    } catch { }
  }

  add('🟥    🟥    🟥      共享服      🟥    🟥    🟥')
  path = '/novel/novels'
  add('小说·共享章节数量', "sort:'chapCount'", 0.4)
  add('小说·共享章节字数', "sort:'charCount'", 0.4)
  add('小说·共享更新时间', "sort:'updateTime'", 0.4)
  add('小说·共享上传时间', "sort:'uploadTime'", 0.4)
  path = '/comic/novels'
  add('漫画·共享章节数量', "sort:'chapCount'", 0.4)
  add('漫画·共享图片数量', "sort:'imageCount'", 0.4)
  add('漫画·共享更新时间', "sort:'updateTime'", 0.4)
  add('漫画·共享上传时间', "sort:'uploadTime'", 0.4)
  path = '/audio/novels'
  add('听书·共享章节数量', "sort:'chapCount'", 0.4)
  add('听书·共享更新时间', "sort:'updateTime'", 0.4)
  add('听书·共享上传时间', "sort:'uploadTime'", 0.4)

  let e1List = ['🟧', '🟨', '🟪']
  let e2List = ['🟠', '🟡', '🟣']
  let index = Math.floor(Math.random() * e1List.length)
  let e1 = e1List[index]
  let e2 = e2List[index]

  let data
  add(`${e1}    ${e1}    ${e1}      ${type}      ${e1}    ${e1}    ${e1}`)

  if (['小说', '听小说', '出版', '短篇'].includes(type)) {
    if (type == '短篇') {
      path = '/novel/short_list'
    } else if (type == '出版') {
      path = '/novel/publish_list'
    } else {
      path = '/novel/list'
    }
    data = requestApiUrl('/novel/explore', { type, tab_type: gender })
  } else if (type == '听书') {
    path = '/audio/list'
    data = requestApiUrl('/audio/explore')
  } else if (type == '漫画') {
    path = '/comic/list'
    data = requestApiUrl('/comic/explore')
  } else if (type == '短剧') {
    path = '/video/list'
    data = requestApiUrl('/video/explore')
  }

  if (type === '短篇') {
    data.forEach(tag => add(tag, `tag:"${tag}"`))
  } else {
    for (let list of data) {
      add(`${e2}    ${list.name}    ${e2}`)
      list.data.forEach(v => {
        add(v.name, `category_id:${v.category_id}`)
      })
    }
  }

}

