let api = 'https://fq.vv9v.cn'

function getApiUrl(path, data = {}) {
  let { source } = this
  data = Object.entries(data).map(v => v.join('=')).join('&')
  let androidId = String(source.get('androidId'))
  if (!androidId) {
    androidId = this.java.androidId()
    source.put('androidId', androidId)
  }
  let option = {
    method: "GET", headers: {
      'x-sec-token': source.getVariable(),
      'x-android-id': androidId
    }
  }
  let url = api + path + '?' + data + ',' + JSON.stringify(option)
  return url
}

function requestApiUrl(path, data) {
  let url = getApiUrl.call(this, path, data)
  try {
    let res = this.java.ajax(url)
    res = JSON.parse(res)
    if (res.error) {
      this.java.longToast(`\n操作失败，code${res.code}：\n${res.error}`)
    }
    if (res.data) {
      return res.data
    }
  } catch (e) {
    this.java.log(`请求共享接口${path}异常：` + e.message)
  }
  return null
}

function getComments(content, bid, cid, cIndex) {
  content = String(content)
  let isPC = this.source.get("段评") == '1'
  let isCC = this.source.get("章评") == '1'
  let isNC = this.source.get("书评") == '1'
  if (!bid || !cid || (!isPC && !isCC && !isNC)) {
    return content
  }
  let lines = content.split('\n')
  try {
    // 段评
    isPC && dealParagraphComment.call(this, lines, bid, cid)
    // 章评
    isCC && dealChapterComment.call(this, lines, bid, cid)
    // 书评
    cIndex == 0 && isNC && dealNovelComment.call(this, lines, bid)
    return lines.join("\n")
  } catch (err) {
    this.java.log(err)
    return content
  }
}

/** 处理段评 */
function dealParagraphComment(lines, bid, cid) {
  /** @type {import('../../src/api/Interface.ts').Novel.CommentParagraphInfo} */
  let data = requestApiUrl.call(this, '/novel/comment/paragraph_info', { bid, cid })
  if (!data) return
  let paragraphIds = Object.keys(data).map(Number)
  if (!paragraphIds.length) return
  // 拼接svg图
  let offset = 0
  paragraphIds.forEach(pid => {
    // this.java.log(`处理段落ID：${pid}，当前偏移量：${offset}`)
    let pIndex = pid + offset
    let pData = data[pid]
    if (lines[pIndex]) {
      while (/<img\s+[^>]*?src="[^"]+"[^>]*>/.test(lines[pIndex])) {
        offset += 1
        pIndex += 1
      }
      if (lines[pIndex] == '') return
      lines[pIndex] += `<img src="data:image/svg+xml;base64,,{"style":"TEXT","type":"fqpl","js":"createSvg('${bid}','${cid}',${pid},${pData.count},${Packages.java.lang.System.nanoTime()})"}">`
      let cacheKey = `fq-${bid}-${cid}-${pid}`
      this.cache.putMemory(cacheKey, '1')
    }
  })
}

function createSvg(bid, cid, pid, count) {
  let cacheKey = `fq-${bid}-${cid}-${pid}`
  let load = this.cache.getFromMemory(cacheKey)
  if (load != '1') {
    let token = this.source.getVariable()
    if (token == '') {
      this.java.longToast('请先在【登录页】获取共享Token后使用本书源')
    } else {
      this.java.startBrowser(`${api}/novel/comment/page?bid=${bid}&cid=${cid}&pid=${pid}&token=${token}`, '评论')
    }
  }
  let color = String(this.source.get('paragraph_comment_svg_color')) || '#FF0000'
  count = count > 999 ? 999 : count
  let svg = `<svg width="1000" height="800" xmlns="http://www.w3.org/2000/svg">
  <rect x="150" y="150" width="665" height="525" rx="175" ry="175" fill="none" stroke="${color}" stroke-width="17.5" />
  <text x="480" y="535" font-family="Arial, sans-serif" text-anchor="middle" dominant-baseline="middle"
    font-size="297.5" fill="${color}">${count}</text>
</svg>`
  let encodedSvg = this.java.base64Encode(svg)
  return `data:image/svg+xml;base64,${encodedSvg}`
}

/** 处理章评 */
function dealChapterComment(lines, bid, cid) {
  let data = requestApiUrl.call(this, '/novel/comment/chapter_info', { bid, cid })
  if (!data) return
  let count = data.item_related_count || 0
  if (!count) return
  if (count > 999) count = 999
  let pid = -1 // 章评pid固定为-1
  lines.push(`<img src="data:image/svg+xml;base64,,{"style":"FULL","type":"fqpl","js":"createSvg2('${bid}','${cid}',${pid},${count},${Packages.java.lang.System.nanoTime()})"}">`)
  let cacheKey = `fq-${bid}-${cid}-${pid}`
  this.cache.putMemory(cacheKey, '1')
}

/** 处理书评 */
function dealNovelComment(lines, bid) {
  let data = requestApiUrl.call(this, '/novel/comment/novel_list', { bid, page: 1 })
  if (!data || !data.common_list_info) return
  let count = data.common_list_info.total || 0
  if (!count) return
  if (count > 999) count = 999
  let cid = -1, pid = -1 // 书评cid、pid固定为-1
  lines.push(`<img src="data:image/svg+xml;base64,,{"style":"FULL","type":"fqpl","js":"createSvg2('${bid}','${cid}',${pid},${count},${Packages.java.lang.System.nanoTime()})"}">`)
  let cacheKey = `fq-${bid}-${cid}-${pid}`
  this.cache.putMemory(cacheKey, '1')
}

function createSvg2(bid, cid, pid, count) {
  let cacheKey = `fq-${bid}-${cid}-${pid}`
  let load = this.cache.getFromMemory(cacheKey)
  if (load != '1') {
    let token = this.source.getVariable()
    if (token == '') {
      this.java.longToast('请先在【登录页】获取共享Token后使用本书源')
    } else {
      this.java.startBrowser(`${api}/novel/comment/page?bid=${bid}&cid=${cid}&pid=${pid}&token=${token}`, '评论')
    }
  }
  let displayText = count > 999 ? 999 : count
  let svg = `<svg width="1000" height="120" xmlns="http://www.w3.org/2000/svg">
  <rect width="1000" height="120" fill="#A9A9A9" rx="15" />
  <text x="100" y="75" font-family="Arial" font-size="48" fill="#000000" text-anchor="start">本${cid == -1 ? '书' : '章'}讨论</text>
  <g transform="translate(850, 60)">
    <rect x="-40" y="-30" width="80" height="60" rx="20" ry="20" stroke="#000000" stroke-width="2" fill="none" />
    <text x="0" y="12" font-family="Arial" font-size="36" fill="#000000" text-anchor="middle"
      dominant-baseline="middle">${displayText}</text>
  </g>
  <text x="965" y="75" font-family="Arial" font-size="36" fill="#000000" text-anchor="middle">〉</text>
</svg>`
  let encodedSvg = this.java.base64Encode(svg)
  return `data:image/svg+xml;base64,${encodedSvg}`
}


